const test = require('node:test');
const assert = require('node:assert');
const { isoDate } = require('../isoDate');
const { reportHeader } = require('../report');
const { reminderSubject } = require('../email');
const { toCsvRow } = require('../export');

test('isoDate zero-pads single-digit month and day', () => {
  assert.strictEqual(isoDate(new Date(Date.UTC(2026, 2, 5))), '2026-03-05');
});

test('isoDate leaves two-digit month and day unchanged', () => {
  assert.strictEqual(isoDate(new Date(Date.UTC(2026, 10, 26))), '2026-11-26');
});

test('reportHeader uses zero-padded date', () => {
  assert.strictEqual(reportHeader(new Date(Date.UTC(2026, 2, 5))), 'Report for 2026-03-05');
});

test('reminderSubject uses zero-padded date', () => {
  assert.strictEqual(
    reminderSubject('INV-9', new Date(Date.UTC(2026, 0, 7))),
    'Invoice INV-9 is due on 2026-01-07'
  );
});

test('toCsvRow uses zero-padded date', () => {
  assert.strictEqual(
    toCsvRow({ id: 42, placedAt: new Date(Date.UTC(2026, 8, 9)), amount: 12.5 }),
    '42,2026-09-09,12.5'
  );
});

